"""Tiny Persian text helpers used for user-facing strings generated by the backend."""

from __future__ import annotations

from datetime import datetime
from decimal import Decimal
from zoneinfo import ZoneInfo

FA_DIGITS = str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹")
AR_TO_EN = str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩٫٬", "01234567890123456789.,")
TEHRAN = ZoneInfo("Asia/Tehran")


def fa_digits(text: str) -> str:
    return text.translate(FA_DIGITS)


def en_digits(text: str) -> str:
    """Persian/Arabic digits and separators -> ASCII (for parsing user input)."""
    return text.translate(AR_TO_EN)


def fa_num(value: float | Decimal | int, decimals: int = 2) -> str:
    """Thousands-separated number in Persian digits, e.g. 1234.5 -> ۱٬۲۳۴٫۵"""
    d = Decimal(str(value))
    q = Decimal(1).scaleb(-decimals) if decimals > 0 else Decimal(1)
    d = d.quantize(q)
    text = f"{d:,.{decimals}f}" if decimals > 0 else f"{d:,.0f}"
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return fa_digits(text.replace(",", "٬").replace(".", "٫"))


def fa_pct(value: float | Decimal, decimals: int = 1) -> str:
    return fa_num(value, decimals) + "٪"


def tehran_time(ts: datetime) -> str:
    return fa_digits(ts.astimezone(TEHRAN).strftime("%Y-%m-%d %H:%M"))
